<script>
(function(){var select=document.getElementById('delivery-zone'),delivery=document.getElementById('checkout-delivery'),total=document.getElementById('checkout-total'),estimate=document.getElementById('delivery-estimate'),subtotal={{ json_encode((float)$subtotal) }},deliveryAmount=0,discountAmount=0,paymentCharge=0;function money(value){return '৳'+Number(value).toLocaleString('en-BD',{maximumFractionDigits:2});}function updateTotal(){total.textContent=money(subtotal-discountAmount+deliveryAmount+paymentCharge);}window.refreshPaymentCharge=function(radio){var base=subtotal-discountAmount+deliveryAmount,enabled=radio&&radio.dataset.chargeEnabled==='1',fee=0;if(enabled){var value=Number(radio.dataset.chargeValue||0),type=radio.dataset.chargeType;if(type==='percentage')fee=base*value/100;else if(type==='fixed_plus_percentage')fee=Number(radio.dataset.minCharge||0)+base*value/100;else fee=value;var min=Number(radio.dataset.minCharge||0),max=Number(radio.dataset.maxCharge||0),free=Number(radio.dataset.freeAbove||0);if(min)fee=Math.max(fee,min);if(max)fee=Math.min(fee,max);if(free&&base>=free)fee=0;}paymentCharge=Math.max(0,fee);document.getElementById('checkout-payment-charge-row').style.display=paymentCharge?'flex':'none';document.getElementById('checkout-payment-charge').textContent=money(paymentCharge);updateTotal();};function refresh(){var option=select.options[select.selectedIndex];if(!option||!option.value){deliveryAmount=0;delivery.textContent='Select zone';estimate.textContent='Choose a zone to see delivery time and charge.';window.refreshPaymentCharge(document.querySelector('.payment-method-radio:checked'));return;}deliveryAmount=Number(option.getAttribute('data-charge')||0);var freeMinimum=Number(option.getAttribute('data-free-minimum')||0);if(freeMinimum>0&&subtotal>=freeMinimum)deliveryAmount=0;delivery.textContent=deliveryAmount===0?'Free':money(deliveryAmount);estimate.textContent=option.getAttribute('data-estimate')?'Estimated delivery: '+option.getAttribute('data-estimate'):'Delivery time will be confirmed after ordering.';window.refreshPaymentCharge(document.querySelector('.payment-method-radio:checked'));}select.addEventListener('change',refresh);refresh();document.getElementById('apply-coupon').addEventListener('click',function(){var button=this,code=document.getElementById('coupon-code').value,message=document.getElementById('coupon-message');button.disabled=true;message.textContent='Checking coupon…';fetch('{{ route('checkout.coupon') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:JSON.stringify({coupon_code:code})}).then(function(response){return response.json().then(function(data){if(!response.ok)throw data;return data;});}).then(function(data){discountAmount=Number(data.discount);document.getElementById('checkout-discount').textContent='−'+money(discountAmount);document.getElementById('checkout-discount-row').style.display='flex';message.textContent=data.message;window.refreshPaymentCharge(document.querySelector('.payment-method-radio:checked'));}).catch(function(data){discountAmount=0;document.getElementById('checkout-discount-row').style.display='none';message.textContent=data.message||'Unable to apply coupon.';window.refreshPaymentCharge(document.querySelector('.payment-method-radio:checked'));}).then(function(){button.disabled=false;});});}());
</script>
<script>(function(){var radios=document.querySelectorAll('.payment-method-radio'),groups=document.querySelectorAll('.emi-plan-group'),details=document.querySelectorAll('[data-payment-detail]');function currentTotal(){return Number(document.getElementById('checkout-total').textContent.replace(/[^0-9.]/g,''))||{{ json_encode((float)$subtotal) }};}function estimate(group){var select=group.querySelector('select'),option=select.options[select.selectedIndex],output=group.querySelector('.emi-estimate');if(!option||!option.value){output.textContent='';return;}var total=currentTotal(),minimum=Number(option.dataset.minimum),months=Number(option.dataset.months),interest=Number(option.dataset.interest),fee=Number(option.dataset.fee);output.textContent=total<minimum?'Minimum order is ৳'+minimum.toLocaleString('en-BD'): 'Estimated ৳'+((total+(total*interest/100)+fee)/months).toLocaleString('en-BD',{maximumFractionDigits:2})+' per month';}function refresh(){var selected=document.querySelector('.payment-method-radio:checked');details.forEach(function(detail){var active=selected&&detail.dataset.paymentDetail===selected.value;detail.style.display=active?'block':'none';detail.querySelectorAll('input,select,textarea').forEach(function(input){input.disabled=!active})});groups.forEach(function(group){var active=selected&&group.dataset.method===selected.value;group.style.display=active?'block':'none';group.querySelector('select').disabled=!active;if(active)estimate(group);});if(window.refreshPaymentCharge)window.refreshPaymentCharge(selected);}radios.forEach(function(radio){radio.addEventListener('change',refresh);});groups.forEach(function(group){group.querySelector('select').addEventListener('change',function(){estimate(group);});});refresh();}());</script>
